  {
   "term": "Generation Z",
   "def": "People born roughly 1997 to 2012, immersed in digital technology since birth."
  },
  {
   "term": "Millennials",
   "def": "People born roughly 1981 to 1996, who witnessed the rise of the internet and social media."
  },
  {
   "term": "Generation Alpha",
   "def": "People born after about 2010 (some sources say 2013), growing up with even more advanced technology such as tablets, smart speakers and AI tools."
  }
